// Web Mercator tile math
function tileXY(lat, lng, z) { const n = 2 ** z const x = Math.floor((lng + 180) / 360 * n) const latRad = lat * Math.PI / 180 const y = Math.floor((1 - Math.log(Math.tan(latRad) + 1/Math.cos(latRad))/Math.PI) / 2 * n) return {x, y}
}
const {x, y} = tileXY(37.7749, -122.4194, 14) // (2620, 6333)
const tiles = for (let dx = -1; dx <= 1; dx++) for (let dy = -1; dy <= 1; dy++) tiles.push(`/tiles/vector/14/${x+dx}/${y+dy}.mvt`)

